using UnityEditor;using UnityEditor.SceneManagement;
public static class GridShiftV26Checks {public static void Export(){SessionState.SetBool("GS26Export",true);Batch();}public static void Batch(){var audit=new System.Collections.Generic.List<string>();foreach(var name in new[]{"MainMenu","SampleScene","Apartment","FactoryInterior"}){var scene=EditorSceneManager.OpenScene("Assets/Scenes/"+name+".unity");foreach(var root in scene.GetRootGameObjects())foreach(var t in root.GetComponentsInChildren<UnityEngine.Transform>(true)){int missing=GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject);if(missing>0)audit.Add(name+"/"+t.name+" missing="+missing);}}System.IO.File.WriteAllLines("Docs/Validacao26/missing-scripts.txt",audit);EditorSceneManager.OpenScene("Assets/Scenes/MainMenu.unity");SessionState.SetBool("GS26Checks",true);EditorApplication.isPlaying=true;}}

